import pandas as pd

from pathlib import Path


# Project root directory
PROJECT_ROOT = Path(__file__).resolve().parent.parent

# Drift results generated by detect_drift.py
RESULTS_PATH = PROJECT_ROOT / "monitoring" / "drift_results.csv"


def calculate_drift_score(results):
    """
    Calculate the percentage of features
    where drift was detected.
    """

    total_features = len(results)

    drifted_features = results[
        results["drift_detected"] == True
    ]

    number_of_drifted_features = len(drifted_features)

    if total_features == 0:
        return 0

    drift_score = (
        number_of_drifted_features / total_features
    ) * 100

    return drift_score


def classify_drift_level(drift_score):
    """
    Classify the overall drift severity.
    """

    if drift_score == 0:
        return "NO DRIFT"

    elif drift_score <= 40:
        return "LOW DRIFT"

    elif drift_score <= 70:
        return "MODERATE DRIFT"

    else:
        return "HIGH DRIFT"


def main():
    print("Loading drift results...")

    results = pd.read_csv(RESULTS_PATH)

    drift_score = calculate_drift_score(results)
    drift_level = classify_drift_level(drift_score)

    total_features = len(results)

    drifted_features = results[
        results["drift_detected"] == True
    ]

    number_of_drifted_features = len(drifted_features)

    print("\n" + "=" * 50)
    print("              DRIFTWATCH REPORT")
    print("=" * 50)

    print(f"Total features checked : {total_features}")
    print(f"Features with drift    : {number_of_drifted_features}")
    print(f"Drift score            : {drift_score:.2f}%")
    print(f"Drift severity         : {drift_level}")

    print("=" * 50)

    if drift_score > 70:
        print("ALERT: Significant data drift detected!")

    elif drift_score > 40:
        print("WARNING: Moderate data drift detected.")

    elif drift_score > 0:
        print("NOTICE: Small amount of data drift detected.")

    else:
        print("STATUS: No data drift detected.")


if __name__ == "__main__":
    main()